+     * news_}로 시작하는 표를 전부 세어 이 목록과 대조한다.
+     */
+    static final List<String> TABLES =
+            List.of(
+                    "news_article_topic",
+                    "news_article_sector",
+                    "news_digest_article",
+                    "news_digest",
+                    "news_article",
+                    "news_topic",
+                    "news_publisher_permission_history",
+                    "news_publisher",
+                    "news_rule_version",
+                    "news_collection_state");
